fn load_cache(root: &Path) -> Arc<DiskCache> {
    let key = normalize_root(root);
    let memo = MEMO.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(cache) = memo.lock().unwrap().get(&key).cloned() {
        return cache;
