  const live = [];
  for (const key of buckets) {
    const dir = join(base, key);
    let st;
    try {
      st = statSync(dir);
      if (!st.isDirectory()) {
        safeRm(dir, removed, key);
        continue;
      }
    } catch {
      continue;
    }
    if (key === currentKey) {
      live.push({ key, path: dir, mtimeMs: st.mtimeMs });
